import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"做交易过程中，你最大的感悟是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易要点.md","filePath":"stock/交易认知/交易要点.md"}'),r={name:"stock/交易认知/交易要点.md"};function s(n,t,c,i,d,l){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="做交易过程中-你最大的感悟是什么" tabindex="-1">做交易过程中，你最大的感悟是什么？ <a class="header-anchor" href="#做交易过程中-你最大的感悟是什么" aria-label="Permalink to &quot;做交易过程中，你最大的感悟是什么？&quot;">​</a></h1><p>呕心沥血，苦思冥想，踩过无数坑，血淋漓的教训，希望对你有帮助：</p><p>设置止损：以小搏大，保障自身资金安全；</p><p>顺势而为：看整体趋势，跟随趋势方向；趋势没结束不要跑！！！</p><p>耐心等待：选好有竞争力的入场点位，我能做的是开仓、设止损，对错交给市场；</p><p>谨慎交易：交易次数不在于多，深思熟虑，顺势交易才能成功；</p><p>克服恐惧：恐惧可以以多种方式表现出来，它可能是害怕错过市场上的良机，也可能是害怕在市场上停留太久而目睹盈利消失。</p><p>勿亏损加仓：可为盈利加仓，不为亏损加仓；</p><p>勿情绪交易：我交易的是市场，不是自身的情绪；</p>',9)]))}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
